import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Custom CUDA kernel for fused bias addition, scaling, and sigmoid
fused_bias_scale_sigmoid_source = r'''
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

__global__ void fused_bias_scale_sigmoid_kernel(const float* __restrict__ x,
                                                const float* __restrict__ bias,
                                                const float* __restrict__ scale,
                                                float* __restrict__ out,
                                                int N, int C, int H, int W) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * C * H * W;
    if (idx < total) {
        int w = idx % W;
        int h = (idx / W) % H;
        int c = (idx / (W * H)) % C;
        int n = idx / (C * H * W);

        float val = x[idx];
        val += bias[c];
        val *= scale[c];
        val = 1.0f / (1.0f + expf(-val));
        out[idx] = val;
    }
}

torch::Tensor fused_bias_scale_sigmoid_cuda(torch::Tensor x,
                                            torch::Tensor bias,
                                            torch::Tensor scale) {
    auto N = x.size(0);
    auto C = x.size(1);
    auto H = x.size(2);
    auto W = x.size(3);

    auto out = torch::zeros_like(x);
    int total = N * C * H * W;

    const int threads = 256;
    int blocks = (total + threads - 1) / threads;

    fused_bias_scale_sigmoid_kernel<<<blocks, threads>>>(
        x.data_ptr<float>(),
        bias.data_ptr<float>(),
        scale.data_ptr<float>(),
        out.data_ptr<float>(),
        N, C, H, W
    );

    return out;
}
'''

fused_bias_scale_sigmoid_cpp_source = r'''
torch::Tensor fused_bias_scale_sigmoid_cuda(torch::Tensor x,
                                            torch::Tensor bias,
                                            torch::Tensor scale);
'''

# Load and compile the custom CUDA extension
fused_bias_scale_sigmoid = load_inline(
    name="fused_bias_scale_sigmoid",
    cpp_sources=fused_bias_scale_sigmoid_cpp_source,
    cuda_sources=fused_bias_scale_sigmoid_source,
    functions=["fused_bias_scale_sigmoid_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    """
    Optimized model that performs a convolution, then fuses bias addition, scaling,
    and sigmoid into a single custom CUDA kernel, followed by group normalization.
    """
    def __init__(self, in_channels, out_channels, kernel_size, num_groups, bias_shape, scale_shape):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self.bias = nn.Parameter(torch.randn(bias_shape))
        self.scale = nn.Parameter(torch.randn(scale_shape))
        self.group_norm = nn.GroupNorm(num_groups, out_channels)

    def forward(self, x):
        x = self.conv(x)
        x = fused_bias_scale_sigmoid.fused_bias_scale_sigmoid_cuda(x, self.bias, self.scale)
        x = self.group_norm(x)
        return x
